        raise ValueError("maxsize must be a positive integer")

    class Node:
        __slots__ = 'func', 'key', 'value', 'count', 'prev', 'next'

        def __init__(self, func, key, value, count=1):
            self.func = func
            self.key = key
            self.value = value
            self.count = count
            self.prev = self.next = None

    class LinkedList:
        __slots__ = 'first', 'last'

        def __init__(self):
            self.first = self.last = None

        def append(self, node):
            if self.last is None:
                self.first = self.last = node
            else:
                node.prev = self.last
                self.last.next = node
                self.last = node

        def move_to_front(self, node):
            if node is self.first:
                return
            if node is self.last:
                self.last = self.last.prev
                self.last.next = None
            node.prev.next = node.next
            node.next.prev = node.prev
            node.prev = None
            node.next = self.first
            self.first.prev = node
            self.first = node

        def pop_last(self):
            ret = self.last
            if ret is not None:
                if ret.prev is not None:
                    ret.prev.next = None
                else:
                    self.first = None
                self.last = ret.prev
            return ret

