        return hash((args, tuple(sorted(kwargs.items())), typed))

    def decorator(func):
        cache = {}
        min_count = None
        count_map = [LinkedList() for _ in range(maxsize + 1)]

        def get_key(args, kwargs):
            return _hash_key(args, kwargs, typed)

        def add_node(func, args, kwargs, value):
            key = get_key(args, kwargs)
            node = Node(func, key, value)
            count_map[1].append(node)
            cache[key] = node
            set_min_count(1)

        def set_min_count(count):
            nonlocal min_count
            while min_count is not None and not count_map[min_count]:
                min_count += 1

        def get_node(args, kwargs):
            key = get_key(args, kwargs)
            node = cache.get(key)
            if node:
                increase_count(node)
                return node
            return None

        def increase_count(node):
            prev_count = node.count
            node.count += 1
            count_map[prev_count].move_to_front(node)
            set_min_count(prev_count)

        def delete_node(node):
            del cache[node.key]
            count_map[node.count].remove(node)

        def wrapper(*args, **kwargs):
