            if node:
                return node.value
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                delete_node(count_map[min_count].pop_last())
            add_node(func, args, kwargs, result)
            return result

        wrapper.cache_info = functools.wraps(func)(lambda: (len(cache), maxsize, cache))
        return wrapper

    return decorator

