            key = args if typed else tuple(sorted(args))
            for entry in data:
                if entry[0] == key:
                    return entry[1]
            return None

        def wrap_cache(func, cache):
            def wrapped(*args, **kwargs):
                result = get(*args)
                if result is None:
                    result = func(*args)
                    put(*args, result)
                return result
            wrapped.put = lambda *args, value: put(*args, value)
            wrapped.forget = lambda *args: put(*args, None)
            wrapped.clear = lambda: put(*args, None for args in data)
            return wrapped

        return wrap_cache(func, cache)

    return decorator

