            key = args if not typed else (func, args, tuple(sorted(kwargs.items())))
            return cache._get_or_insert(key, lambda: func(*args, **kwargs))

        def get(*args, **kwargs):
            key = args if not typed else (func, args, tuple(sorted(kwargs.items())))
            return cache._get(key)

        def delete(*args, **kwargs):
            key = args if not typed else (func, args, tuple(sorted(kwargs.items())))
            return cache._popitem()

        def clear():
            cache._clear()

        wrapper.get = get
        wrapper.delete = delete
        wrapper.clear = clear

        return wrapper

