def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    base_classes = list(classes)
    while True:
        changed = False
        for cls in base_classes[:]:
            for base in cls.__bases__:
                if base in base_classes:
                    base_classes.remove(base)
                    changed = True
        if not changed:
            break
    return base_classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    while True:
        new_classes = []
        for cls in classes:
            if cls.__bases__ and all(b in classes for b in cls.__bases__):
                continue
            new_classes.append(cls)
        if new_classes == classes:
            break
        classes = new_classes
    return classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    seen = set()
    result = []

    def add_class(cls):
        if cls in seen:
            return
        seen.add(cls)
        for base in cls.__bases__:
            add_class(base)
        result.append(cls)

    for cls in classes:
        add_class(cls)

    return result

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not classes:
        return []

    base_classes = []
    for cls in classes:
        bases = set(cls.__bases__)
        while bases:
            common = bases.intersection(base_classes)
            if common:
                bases -= common
            else:
                break
        base_classes.extend(bases)

    return sorted(base_classes, key=classes.index)

