def _validate_labels(labels, label_key_regex=None, label_value_regex=None):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    if label_key_regex is None:
        label_key_regex = r'^[a-zA-Z0-9_][a-zA-Z0-9_-]*$'
    if label_value_regex is None:
        label_value_regex = r'^[\x00-\x7F]+$'

    errors = []
    for key, value in labels.items():
        try:
            if not re.match(label_key_regex, key):
                errors.append({str(key): "Label key '{}' does not match the regex {}".format(key, label_key_regex)})
            if isinstance(value, list):
                for v in value:
                    if not re.match(label_value_regex, v):
                        errors.append({str(v): "Invalid value '{}' for label value. Expected string or bytes-like object".format(v)})
            else:
                if not re.match(label_value_regex, value):
                    errors.append({str(value): "Invalid value '{}' for label value. Expected string or bytes-like object".format(value)})
        except TypeError:
            errors.append({str(key): "Invalid value '{}' for label key. Expected string or bytes-like object".format(key)})

    if errors:
        raise ValidationError(messages=errors)

