    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for member in zip_ref.infolist():
                if member.filename.endswith('.xml'):
                    xml_bname = os.path.splitext(member.filename)[0]
                    if xml_bname not in result:
                        result[xml_bname] = {}
                    result[xml_bname][member.filename] = zip_ref.read(member.filename)
    except Exception as e:
        print(f"Error exploring zipfile: {e}")
        result = {}

    return result

