def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extracts the number and supplement from the content of <issue>xxxx</issue>.

    :param issue: The content of the <issue> tag to extract the number and supplement from.
    :returns: A tuple containing the extracted number and supplement.
    """
    issue = issue.strip().lower()
    parts = issue.split()
    number = None
    supplement = None

    for i, part in enumerate(parts):
        if part.isdigit():
            number = part
            if i + 1 < len(parts):
                supplement = parts[i + 1]
                if supplement.lower().startswith('suppl'):
                    supplement = supplement[5:].strip()
                elif supplement.lower() in ['spe', 'pr']:
                    supplement = f'{number} {supplement}'

    return number, supplement

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    number = None
    suppl = None
    issue = issue.strip()

    if 'suppl' in issue.lower():
        suppl = 'suppl'
    if 'spe' in issue.lower():
        suppl = 'spe'

    if issue.isdigit():
        number = issue
    elif '-' in issue:
        parts = issue.split('-')
        if parts[0].isdigit() and parts[1].isdigit():
            number = parts[0]
    elif ' ' in issue:
        parts = issue.split()
        if parts[0].isdigit():
            number = parts[0]
        if 'suppl' in parts[1].lower():
            suppl = 'suppl'
        if 'spe' in parts[1].lower():
            suppl = 'spe'

    if suppl:
        if number:
            suppl += ' ' + number
        else:
            suppl += ' 1'

    return number, suppl

