    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify(expr):
        if isinstance(expr, (list, tuple)) and len(expr) == 2:
            op, a, b = '', expr[0], expr[1]
            if expr[0] == '&':
                if a == b:
                    return a
                elif a == '~' and isinstance(b, list) and len(b) == 2 and b[0] == '|':
                    c, d = b[1], b[2]
                    if c == a[1]:
                        return d
                    elif d == a[1]:
                        return c
            elif expr[0] == '|':
                if a == b:
                    return a
                elif a == '~' and isinstance(b, list) and len(b) == 2 and b[0] == '&':
                    c, d = b[1], b[2]
                    if c == a[1]:
                        return d
                    elif d == a[1]:
                        return c
        return expr

    result = []
    for expr in args:
        result.append(simplify(expr))
    return result

