    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        root = self.get_root()
        num_objects += self._validate_node(root, validate_objects, check_digests, show_warnings)
        good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Warning: Failed to validate root node. Error: {e}")

    try:
        for child in self.get_children():
            num_objects += self._validate_node(child, validate_objects, check_digests, show_warnings)
            good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Warning: Failed to validate children nodes. Error: {e}")

    return num_objects, good_objects

def _validate_node(self, node, validate_objects, check_digests, show_warnings):
    """Validate a single node and its children.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    if node.is_object():
        num_objects += 1
        if validate_objects:
            try:
                node.validate_objects()
                good_objects += 1
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Failed to validate object. Node ID: {node.id}, Error: {e}")

    if node.is_container():
        num_objects += 1
        if check_digests:
            try:
                node.check_digests()
                good_objects += 1
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Failed to validate digests. Node ID: {node.id}, Error: {e}")

    for child in node.get_children():
        num_objects += self._validate_node(child, validate_objects, check_digests, show_warnings)
        good_objects += 1

    return num_objects, good_objects

