    '''
    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        # Find the argument indices for the current subparser
        for i, arg in enumerate(remaining_args):
            if arg.startswith(f"--{subparser_name}") or arg.startswith(f"-{subparser_name[0]}"):
                # Parse the arguments starting from the current index
                namespace, remaining_unparsed = subparser.parse_known_args(remaining_args[i:])
                parsed_args[subparser_name] = namespace
                remaining_args = remaining_unparsed[i:]
                break

    return parsed_args, remaining_args

