    etc.) does not completely replace the corresponding section in a merged file.
    '''
    merged_dict = {}
    for key, value in nodes:
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            if key not in merged_dict or not isinstance(merged_dict[key], ruamel.yaml.nodes.MappingNode):
                merged_dict[key] = value
            else:
                merged_dict[key] = deep_merge_nodes([
                    (k, v) for k, v in zip(value.value, value.value)
                ])
        else:
            merged_dict[key] = value

    return [(key, value) for key, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged_dict = {}
    for key, value in nodes:
        if key.value not in merged_dict:
            merged_dict[key.value] = value
        else:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                if isinstance(merged_dict[key.value], ruamel.yaml.nodes.MappingNode):
                    merged_dict[key.value] = ruamel.yaml.comments.CommentedMap()
                    for k, v in value.value:
                        if k.value in merged_dict[key.value]:
                            if isinstance(v, ruamel.yaml.nodes.MappingNode):
                                if isinstance(merged_dict[key.value][k.value], ruamel.yaml.nodes.MappingNode):
                                    merged_dict[key.value][k.value] = deep_merge_nodes([(k, v)])
                                else:
                                    merged_dict[key.value][k.value] = v
                            else:
                                merged_dict[key.value][k.value] = v
                        else:
                            merged_dict[key.value][k.value] = v
                else:
                    merged_dict[key.value] = deep_merge_nodes([(key, merged_dict[key.value])])
            else:
                merged_dict[key.value] = value
    return list(merged_dict.items())

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged = {}

    for key, value in nodes:
        if key not in merged:
            merged[key] = value
        elif isinstance(merged[key], ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
            merged[key] = ruamel.yaml.nodes.MappingNode(
                tag=value.tag,
                value=deep_merge_nodes(
                    list(zip(
                        merged[key].value.keys(),
                        merged[key].value.values()
                    )) + list(zip(
                        value.value.keys(),
                        value.value.values()
                    )))
            )

    return merged.items()

def deep_merge_nodes(nodes):
    result = {}
    for key, value in nodes:
        if key not in result:
            result[key] = value
        else:
            if isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = deep_merge_nodes(list(zip(result[key].items(), value.items())))
            else:
                result[key] = value
    return [(key, value) for key, value in result.items()]

