def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''

    import argparse
    import sys

    class SubParsersAction(argparse._SubParsersAction):
        # To allow the subparsers are created even if no commands are invoked
        def __call__(self, parser, namespace, values, option_string=None):
            setattr(namespace, self.dest, self._name_parser_map)

    def from_unparsed(cls, unparsed, *, namespace=None):
        parser = cls()
        parser._parser = parser._actions[0].parser
        parser._parser.register('action', 'parsersub', SubParsersAction)

        args, _ = parser.parse_known_args(unparsed, namespace=namespace)
        nsmap = {}
        for action in parser._parser._get_subactions():
            if not isinstance(action, argparse._SubParsersAction):
                continue
            for _, subns in vars(action.dest).items():
                nsmap[subns.prog[len(action.prog) + 2:]] = subns
        return nsmap

    return from_unparsed(argparse.ArgumentParser, unparsed_arguments, namespace=None)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    arg_results = {}
    remaining_args = list(unparsed_arguments)
    for subparser_name, parser in subparsers.items():
        original_remaining_args_length = len(remaining_args)
        try:
            namespace, remaining_args = parser.parse_known_args(remaining_args)
            arg_results[subparser_name] = namespace
        except SystemExit:
            # If argparse tries to exit, it means it didn't find any匹配的参数.
            remaining_args = remaining_args[original_remaining_args_length:]
    return arg_results, remaining_args

