def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    units = {'K': 1024, 'M': 1024**2, 'G': 1024**3, 'T': 1024**4, 'P': 1024**5, 'E': 1024**6, 'Z': 1024**7, 'Y': 1024**8}

    if size[-1] in units:
        number = float(size[:-1])
        return int(number * units[size[-1]])
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('B'):
        return int(size[:-1])
    elif size.endswith('K'):
        return int(size[:-1]) * 1024
    elif size.endswith('M'):
        return int(size[:-1]) * 1024 ** 2
    elif size.endswith('G'):
        return int(size[:-1]) * 1024 ** 3
    elif size.endswith('T'):
        return int(size[:-1]) * 1024 ** 4
    elif size.endswith('P'):
        return int(size[:-1]) * 1024 ** 5
    elif size.endswith('E'):
        return int(size[:-1]) * 1024 ** 6
    elif size.endswith('Z'):
        return int(size[:-1]) * 1024 ** 7
    elif size.endswith('Y'):
        return int(size[:-1]) * 1024 ** 8
    else:
        raise ValueError("Invalid file size format")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                if isinstance(result[key], list) and isinstance(value, (list, dict)):
                    result[key].extend(value)
                else:
                    result[key] += value
            else:
                result[key] = value

    return result

