def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number > 0:
        digits.append(number % base)
        number //= base

    result = ''.join(alphabet[digit] for digit in reversed(digits))

    if padding is not None:
        result = result.zfill(padding)

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    base = len(alphabet)
    digits = []

    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None:
        digits.extend([alphabet[0]] * (padding - len(digits)))

    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if number < 0:
        raise ValueError("Number cannot be negative")

    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two characters")

    if not isinstance(padding, (int, type(None))):
        raise TypeError("Padding must be an integer or None")

    if padding is not None and padding < 0:
        raise ValueError("Padding cannot be negative")

    result = ""
    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if padding is not None:
        result = result.zfill(padding)

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if number < 0:
        raise ValueError("Number must be non-negative")

    if padding is not None and padding < 0:
        raise ValueError("Padding must be a non-negative integer")

    if padding is not None and number >= (len(alphabet) ** padding):
        raise ValueError("Number too large for the given padding")

    base = len(alphabet)
    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base
    result = ''.join(reversed(digits))

    if padding is not None:
        result = result.zfill(padding)

    return result

