import os
from pathlib import PosixPath
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """

    if not os.path.exists(archive_path):
        raise ValueError(f"Archive does not exist: {archive_path}")

    if isinstance(tmp_path, str):
        tmp_path = PosixPath(tmp_path)

    if not tmp_path.is_dir():
        raise ValueError(f"Temporary path is not a directory: {tmp_path}")

    if not filename:
        filename = archive_path.split(os.path.sep)[-1]
        filename = filename.split('.')[0]  # Remove extension

    extract_path = tmp_path / filename
    extract_path.mkdir(exist_ok=True, parents=True)

    if archive_path.endswith('.tar.gz'):
        subprocess.run(['tar', '-xzf', archive_path, '-C', extract_path], check=True)
    elif archive_path.endswith('.tar.bz2'):
        subprocess.run(['tar', '-xjf', archive_path, '-C', extract_path], check=True)
    elif archive_path.endswith('.zip'):
        subprocess.run(['unzip', archive_path, '-d', extract_path], check=True)
    else:
        raise ValueError(f"Unsupported archive type: {archive_path}")

    repo_url = f"file://{extract_path}"
    return repo_url

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''

    try:
        output, status = subprocess.Popen(["git", "ls-files", "--exclude-standard"], stdout=subprocess.PIPE)
        if status != 0:
            raise Exception("Failed to obtain the file names")

        files = output.decode('utf-8').strip().split('\n')
        ignored_files = [file for file in files if file in ignored]
        ignored_files.sort()

        return ', '.join(ignored_files)
    except Exception as e:
        print(f"Error: {e}")
        return ""

