import datetime
def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    units = {
        "seconds": "seconds",
        "minutes": "minutes",
        "hours": "hours",
        "days": "days",
        "weeks": "weeks",
        "months": "days",  # Approximate
        "years": "days"    # Approximate
    }
    m = re.match(r'(\d+)\s*(\w+)', frequency, re.IGNORECASE)
    if not m:
        raise ValueError("Invalid frequency format")
    count = int(m.group(1))
    unit = m.group(2).lower()
    if unit not in units:
        raise ValueError("Invalid time unit")
    if units[unit] == "days":
        count *= 30  # Approximate
    return datetime.timedelta(**{units[unit]: count})

