        "minutes": "minutes",
        "hours": "hours",
        "days": "days",
        "weeks": "weeks",
        "months": "months",
        "years": "years"
    }
    for unit, time_unit in time_units.items():
        if unit in frequency:
            try:
                num = int(frequency.replace(unit, ""))
                return getattr(datetime.timedelta, time_unit)(num)
            except (ValueError, AttributeError):
                raise ValueError(f"Invalid frequency: {frequency}")
