from rdflib import Graph, URIRef, Literal
from typing import Optional, Set, Any

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set[Any]] = None
) -> Set[Any]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    children = set(graph.subjects(pred=prop))

    for child in children:
        parents = set(graph.objects(child, prop))
        if not parents:
            roots.add(child)
        else:
            for parent in parents:
                find_roots(graph, prop, roots)

    return roots

import rdflib from rdflib.namespace import RDFS def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:  
    if roots is None:  
        roots = set()  
    for s, p, o in graph.triples((None, prop, None)):  
        if p == prop:  
            roots.discard(s)  
        else:  
            roots.add(s)  
    return roots

