                if overrides:
                    config.update(overrides)

                if resolve_env:
                    config = resolve_environment_variables(config)

                configs[filename] = config
        except Exception as e:
            errors.append(LogRecord('load_configurations', 40, filename, 0, 'Failed to load %s: %s', (filename, str(e)), None))

    return configs, errors

def resolve_environment_variables(config):
    for key, value in config.items():
        if isinstance(value, dict):
            config[key] = resolve_environment_variables(value)
        elif isinstance(value, str) and value.startswith('${') and value.endswith('}'):
            env_var = value[2:-1]
            if env_var in os.environ:
                config[key] = os.environ[env_var]
            else:
                config[key] = None
    return config

