def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content

    coordinates = {
        "left": 0,
        "right": 1,
        "middle": 0.5
    }

    field_count = len(field_names)
    scale_used = False

    if scale is True:
        scale_used = True

    graph_data = []
    for bin_data in hist.bins:
        bin_content = bin_data.content
        value = make_value(bin_content)

        if isinstance(value, tuple):
            value = list(value)
            if field_count != len(value):
                raise ValueError("Number of value fields must match field_names")
        elif field_count != 1:
            raise ValueError("Number of value fields must match field_count")

        coord = getattr(bin_data, get_coordinate)
        graph_point = [coord] + value

        if scale_used:
            graph_point = [bin_data.scale * coord] + value

        graph_data.append(graph_point)

    return graph_data

