def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from xml.etree import ElementTree as ET
        from xml.dom import minidom
        from Crypto.PublicKey import RSA
        from Crypto.Signature import PKCS1_v1_5
        from Crypto.Hash import SHA256
    except ImportError:
        print("Please install the required libraries: pycryptodome")
        return False

    if isinstance(public_key, str):
        public_key = RSA.import_key(public_key)

    try:
        root = ET.fromstring(doc)
    except ET.ParseError:
        return False

    for elem in root.iter():
        if 'signature' in elem.tag:
            sigElem = elem
            break
    else:
        return False

    sigValue = base64.b64decode(sigElem.text)
    msg = minidom.parseString(doc).toprettyxml(codec='utf-8')
    h = SHA256.new(msg)
    vk = PKCS1_v1_5.new(public_key)
    return vk.verify(h, sigValue)

