def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if key not in dic:
        dic[key] = {}
    if not keys:
        dic[key] = val
    else:
        next_key = keys[0]
        if next_key not in dic[key]:
            dic[key][next_key] = {}
        dict_insert(dic[key], val, next_key, *keys[1:])

