    """List all file names in the given directories based on the specified option."""
    try:
        if not settings_dirs or not isinstance(settings_dirs, list):
            return []

        files_list = []
        for directory in settings_dirs:
            for root, _, files in os.walk(directory):
                for file in files:
                    if spec_option == 'all':
                        files_list.append(os.path.join(root, file))
                    elif spec_option == 'py_files' and file.endswith('.py'):
                        files_list.append(os.path.join(root, file))
                    elif spec_option == 'txt_files' and file.endswith('.txt'):
                        files_list.append(os.path.join(root, file))
                    # Add more conditions as needed
        return files_list
    except Exception as e:
        return str(e)

