            items[new_key] = v
    return items

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        import json
        from os.path import join
        from os import listdir

        flatten_dict = {}

        # Traverse the directory to find the spec file
        for file_name in listdir(plugin_dir):
            if file_name.endswith('.spec'):
                spec_file_path = join(plugin_dir, file_name)

                # Read and parse the spec file
                with open(spec_file_path, 'r') as file:
                    spec_data = json.load(file)

                    # Flatten the dictionary
                    for key, value in spec_data.items():
                        if isinstance(value, dict):
                            flatten_dict.update({f'{key}_{子key}': 子值 for 子key, 子值 in value.items()})
                        else:
                            flatten_dict[key] = value

        return flatten_dict

    except FileNotFoundError:
        print(f"Spec file not found in {plugin_dir}")
        return None
    except json.JSONDecodeError:
        print(f"Error decoding JSON in {plugin_dir}")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

def get_plugin_spec_flatten_dict(plugin_dir):
